/*
G_ij = { P_ij + J_ij  if  ( i , j ) ∈ E
        0 otherwise

        G_jk += { ( j , k ) ∈ F : P_jk + J_jk
        0 otherwise

        where
        P: ℝ ^ (4 × 4): a matrix
        J: ℝ ^ (4 × 4): a matrix
        G: ℝ ^ (10 × 10): a matrix
        E: { ℤ × ℤ } index
        F: { ℤ × ℤ } index
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    Eigen::SparseMatrix<double> G;

    heartlib(
        const Eigen::Matrix<double, 4, 4> & P,
        const Eigen::Matrix<double, 4, 4> & J,
        const std::vector<std::tuple< int, int > > & E,
        const std::vector<std::tuple< int, int > > & F)
    {

        // G_ij = { P_ij + J_ij  if  ( i , j ) ∈ E
        //         0 otherwise
        G.resize(10, 10);
        std::vector<Eigen::Triplet<DT> > tripletList_G;
        for(const std::tuple< int, int >& tuple : E){
            int i = std::get<0>(tuple)+1;
            int j = std::get<1>(tuple)+1;
            tripletList_G.push_back(Eigen::Triplet<DT>(i-1, j-1, P(i-1, j-1) + J(i-1, j-1)));
        }
        G.setFromTriplets(tripletList_G.begin(), tripletList_G.end());
        // G_jk += { ( j , k ) ∈ F : P_jk + J_jk
        //         0 otherwise
        for(const std::tuple< int, int >& tuple : F){
            int j = std::get<0>(tuple)+1;
            int k = std::get<1>(tuple)+1;
            tripletList_G.push_back(Eigen::Triplet<DT>(j-1, k-1, P(j-1, k-1) + J(j-1, k-1)));
        }
        G.setFromTriplets(tripletList_G.begin(), tripletList_G.end());
    }
};

