function output = heartlib(P, J, E, F)
% output = heartlib(P, J, E, F)
%
%    G_ij = { P_ij + J_ij  if  ( i , j ) ∈ E
%            0 otherwise
%    
%            G_jk += { ( j , k ) ∈ F : P_jk + J_jk
%            0 otherwise
%    
%            where
%            P: ℝ ^ (4 × 4): a matrix
%            J: ℝ ^ (4 × 4): a matrix
%            G: ℝ ^ (10 × 10): a matrix
%            E: { ℤ × ℤ } index
%            F: { ℤ × ℤ } index
    assert( isequal(size(P), [4, 4]) );
    assert( isequal(size(J), [4, 4]) );
    assert(size(E,2) == 2)
    assert(size(F,2) == 2)

    % G_ij = { P_ij + J_ij  if  ( i , j ) ∈ E
    %         0 otherwise

    Gij_0 = zeros(2,0);
    Gvals_0 = zeros(1,0);
    for index = 1:size(E, 1)
        i = E(index, 1);
        j = E(index, 2);
        Gij_0(1:2,end+1) = [i;j];
        Gvals_0(end+1) = P(i, j) + J(i, j);
    end
    sparse_0 = sparse(Gij_0(1,:),Gij_0(2,:),Gvals_0,10,10);
    G = sparse_0;
    % G_jk += { ( j , k ) ∈ F : P_jk + J_jk
    %         0 otherwise

    Gij_0 = zeros(2,0);
    Gvals_0 = zeros(1,0);
    for index_1 = 1:size(F, 1)
        j = F(index_1, 1);
        k = F(index_1, 2);
        Gij_0(1:2,end+1) = [j;k];
        Gvals_0(end+1) = P(j, k) + J(j, k);
    end
    G = scipy.sparse.coo_matrix((Gvals_0+G.data.tolist(), np.hstack((np.asarray(Gij_0).T, np.asarray((G.row, G.col))))), shape=(10, 10))
    G = G;
    output.G = G;
end

